# Audio controller for serving generated TTS audio files
#
# This controller handles serving audio files generated by the TTS service.
# It retrieves audio data from storage and serves it with proper headers.
class AudioController < ApplicationController
  include AudioResponseHandler
  
  # Input validation for audio ID
  before_action :validate_audio_id_before_show, only: [:show]
  
  # Serve audio file by ID
  def show
    audio_id = params[:id]
    
    log_info "Serving audio file", context: { audio_id: audio_id }
    
    begin
      # Fetch audio data from TTS service storage
      audio_data = Ai::TtsService.fetch_audio(audio_id)
      
      unless audio_data&.dig(:success)
        log_warn "Audio not found for ID: #{audio_id}"
        render_audio_error("Audio file not found")
        return
      end
      
      # Check if audio content exists
      unless audio_data[:audio_content].present?
        log_error "Audio content is missing for audio ID: #{audio_id}", context: { 
          audio_data_keys: audio_data.keys,
          has_success: audio_data[:success]
        }
        render_audio_error("Audio content not available")
        return
      end
      
      # Decode the base64 audio content with error handling
      audio_content = decode_audio_content(audio_data[:audio_content], audio_id)
      unless audio_content
        render_audio_error("Invalid audio data format")
        return
      end
      
      # Serve the audio content with proper headers
      mime_type = audio_data[:mime_type] || 'audio/wav'
      serve_audio_content(audio_content, audio_id, mime_type: mime_type)
                
    rescue => e
      log_error "Unexpected error serving audio file", context: { 
        audio_id: audio_id,
        error: e.message,
        backtrace: e.backtrace.first(5)
      }
      render_audio_error("Error loading audio file")
    end
  end
  
  private
  
  # Validate audio ID parameter using the concern method
  def validate_audio_id_before_show
    validate_audio_id_param(params[:id])
  end
end
